Code_Content:
GRID_SIZE = 300
GRID_SERIAL = 8772

def calculate_power(x, y):
    rack_id = x + 10
    power_level = rack_id * y
    power_level += GRID_SERIAL
    power_level *= rack_id
    power_level = power_level // 100 % 10
    return power_level - 5

def init_grid():
    grid = [[0 for _ in range(GRID_SIZE)] for _ in range(GRID_SIZE)]
    for y in range(GRID_SIZE):
        for x in range(GRID_SIZE):
            grid[y][x] = calculate_power(x, y)
    return grid

# thanks chatgpt, for pointing out the summed-area table calculation
def init_summed_area_table(grid):
    summed_area = [[0 for _ in range(GRID_SIZE + 1)] for _ in range(GRID_SIZE + 1)]
    for y in range(1, GRID_SIZE + 1):
        for x in range(1, GRID_SIZE + 1):
            summed_area[y][x] = grid[y - 1][x - 1] \
                              + summed_area[y - 1][x] \
                              + summed_area[y][x - 1] \
                              - summed_area[y - 1][x - 1]
    return summed_area

def get_submatrix_sum(x1, y1, x2, y2):
    return summed_area[y2 + 1][x2 + 1] \
         - summed_area[y1][x2 + 1] \
         - summed_area[y2 + 1][x1] \
         + summed_area[y1][x1]


grid = init_grid()
summed_area = init_summed_area_table(grid)

def part1(size):
    max_power = float('-inf')
    best_coords = (0, 0)
    for y in range(GRID_SIZE - size + 1):
        for x in range(GRID_SIZE - size + 1):
            submatrix_sum = get_submatrix_sum(x, y, x + size - 1, y + size - 1)
            if submatrix_sum > max_power:
                max_power = submatrix_sum
                best_coords = (x, y)
    return (best_coords, max_power)


def part2():
    max_power = float('-inf')
    best_coords = (0, 0)
    best_size = 0

    for size in range(1, GRID_SIZE + 1):
        coords, power = part1(size)
        if power > max_power:
            max_power = power
            best_coords = coords
            best_size = size

    return (best_coords, best_size)


print("Part 1: ", part1(3))
print("Part 2: ", part2())

#!/usr/bin/env python3
import os
import sys
import re
import subprocess
import qrcode
import colorama

import constants

def get_platform() -> str:
    """
    Returns the name of the platform where the application is currently running
    """
    platforms = {
        'linux': constants.LINUX,
        'linux1': constants.LINUX,
        'linux2': constants.LINUX,
        'darwin': constants.MAC,
        'win32': constants.WINDOWS
    }

    if not sys.platform in platforms:
        return sys.platform

    return platforms[sys.platform]

def get_profiles() -> list:
    """
    Gets a list of names from saved wifi networks in the current platform
    """
    profiles = []

    platform = get_platform()

    try:
        if platform == constants.MAC:
            # Command found here : https://coderwall.com/p/ghl-cg/list-known-wlans
            profiles = run_command(f"defaults read ~/Library/Logs/com.apple.wifi.syncable-networks.plist | grep \" SSID\" | sed 's/^.*= \(.*\);$/\\1/' | sed 's/^\"\\(.*\)\"$/\\1/'").split('\n')
        elif platform == constants.LINUX:
            if os.getuid() != 0:
                ssid = run_command(f"sudo ls /etc/NetworkManager/system-connections/ | grep .nmconnection").split('\n')
            else:
                ssid = run_command(f"ls /etc/NetworkManager/system-connections/ | grep .nmconnection").split('\n')

            for entry in ssid:
                profiles.append(entry.split('.nmconnection')[0])
        elif platform == constants.WINDOWS:
            # Reference: https://www.geeksforgeeks.org/getting-saved-wifi-passwords-using-python/
            # getting meta data
            meta_data = run_command('netsh wlan show profiles | findstr ":"')

            if meta_data != "":
                # splitting data line by line
                data = meta_data.split('\n')

                if len(data) > 0:
                    # skip the first element in data since it does not contain a valid profile returned by netsh command
                    profiles = [d.split(':')[1].strip(' .\r') for d in data[1:]]
    except Exception as ex:
        print(f'Error: {ex}')

    return profiles

def generate_wifi_dict(profiles: list) -> dict:
    """
    Generates a dictionary with the wifi name as key and the password as it's value
    """
    wifi_dict = {}

    if profiles is None:
        print(f'List is not defined.')
        return

    if len(profiles) == 0:
        print(f'List is empty.')
        return

    for ssid in profiles:
        if get_platform() == constants.MAC and len(profiles) > 1:
            password = "*****"
        else:
            password = get_password(ssid)

        wifi_dict[ssid] = password

    return wifi_dict

def get_password(ssid: str) -> str:
    """
    Gets the password for a given SSID
    """
    password = ""

    if ssid == "" or ssid is None:
        print("SSID is not defined")
        return password

    platform = get_platform()

    try:
        if platform == constants.MAC:
            password = run_command(f"security find-generic-password -l \"{ssid}\" -D 'AirPort network password' -w")
        elif platform == constants.LINUX:
            # Check if the user is running with super user privilages
            if os.getuid() != 0:
                password = run_command(f"sudo nmcli -s -g 802-11-wireless-security.psk connection show '{ssid}'")
            else:
                password = run_command(f"nmcli -s -g 802-11-wireless-security.psk connection show '{ssid}'")
        elif platform == constants.WINDOWS:
            password = run_command(f"chcp 437 | netsh wlan show profile name=\"{ssid}\" key=clear | findstr Key")

            if password != "":
                password = re.findall(r"Key Content\s+:\s(.*)", password)

                if len(password) > 0:
                    password = password[0]
                else:
                    password = ""
    except Exception as ex:
        print(f'Error: {ex}')

    return password

def run_command(command: str) -> str:
    """
    Runs a given command using subprocess module
    """
    if command == "" or command is None:
        return ""

    env = os.environ.copy()
    env["LANG"] = "C"
    output, _ = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, shell=True, env=env).communicate()
    return output.decode("utf-8", errors="replace").rstrip("\r\n")

def print_dict(ssid: dict) -> None:
    """
    Prints the contents of the given dictionary that contains the wifi name and password
    """
    if ssid is None:
        print(f'Dictionary is not defined.')
        return

    if len(ssid) == 0:
        print(f'Dictionary is empty.')
        return

    print("----------------------------------------------")
    print("{:<30}| {:<}".format("SSID", "Password"))
    print("----------------------------------------------")

    for key, value in ssid.items():
        print("{:<30}| {:<}".format(key, value))

    print("----------------------------------------------")
    # If macOS and list 

    if get_platform() == constants.MAC and len(ssid) > 1:
        print(f"Use 'wifi-password -s <SSID>' to find a specific WIFI password")

def generate_qr_code(ssid: str, password: str, path: str, show_qr: bool) -> None:
    """
    Generates a QR code from a given ssid and password

    Source: https://git.io/JtLIv
    """
    if ssid == "" or ssid is None:
        print('SSID is not specified, cannot generate QR code.')
        return

    text = f"WIFI:T:WPA;S:{ssid};P:{password};;"

    try:
        qr = qrcode.QRCode(version=1,
                        error_correction=qrcode.constants.ERROR_CORRECT_L,
                        box_size=10,
                        border=4)
        qr.add_data(text)

        if show_qr:
            print(f'---------- {ssid} ----------')
            # This will emulate support for ANSI escape sequences, which is needed
            # in order to display the QR code on Windows
            colorama.init()
            qr.make()
            qr.print_tty()

        if path:
            file_name = ssid.replace(" ", "_") + ".png"

            if path == "STORE_LOCALLY":
                path = file_name

            try:
                img = qr.make_image()
                img.save(path)

                print(f"QR code has been saved to {path}")
            except FileNotFoundError:
                print(f"No such file/directory: '{path}'")
    except Exception as ex:
        print(f'QR Code Error: {ex}')

from collections import defaultdict
from typing import List

# Wrong, but fun application of tries

def trie():
    return defaultdict(trie)


def build_trie_from_words(words: List[str]) -> dict:
    word_trie = trie()

    for word in words:
        current_pointer = word_trie
        for char in word:
            current_pointer = current_pointer[char]

        current_pointer["end"] = True

    return word_trie


def get_longest_gestaltwort(words: List[str]):
    word_trie = build_trie_from_words(words)

    c_max_len = 0
    c_max_word = 0

    for word in words:
        if is_composite(word, word_trie):
            if len(word) > c_max_len:
                c_max_len = len(word)
                c_max_word = word
    return c_max_word


def is_composite(word: str, word_trie: dict) -> bool:
    possible_split_pointers = []

    trie_pointer = word_trie
    for c in word:
        new_trie_pointer = trie_pointer[c]

        i = 0
        while i < len(possible_split_pointers):
            trie_pointer_subword = possible_split_pointers[i]
            if c not in trie_pointer_subword:
                possible_split_pointers.pop(i)
            else:
                possible_split_pointers[i] = trie_pointer_subword[c]
                i += 1

        if "end" in new_trie_pointer:
            possible_split_pointers.append(word_trie)

        # print(f"Char: {c} of {word}, current trie elems: {list(trie_pointer[c])},"
        #       f"\tpossible split pointers {[x.keys() for x in possible_split_pointers]}")
        trie_pointer = new_trie_pointer

    return any("end" in x for x in possible_split_pointers)


"""
for each word:
    check if partition exists
    for each char:
        if end of word in trie
            push to beginning
            add to possible split pointers

        for each of possible split pointes:
            advance to next letter if possible
            if not remove them from possible split pointers

for possible pointers:
    if any is at the end of a word, there is a valid partition
    record length against max
"""


def sys_word_test():
    with open("/usr/share/dict/words", "r") as system_words_file:
        big_list = list(map(lambda word: word.lower(),
                            system_words_file.read().split("\n")))

    print(f"Have a total of {len(big_list)} words")
    print(f"The longest is: {sorted(big_list, key = len)[-1]}")

    print(
        f"For the words, the longest is {get_longest_gestaltwort(big_list[1:])}")


if __name__ == "__main__":
    words = ["cat", "banana", "dog", "nana",
             "walk", "walker", "dogwalker", "catdognana"]
    print(f"For the words, the longest is {get_longest_gestaltwort(words)}")

