# Our own host and port info
global_host = 'localhost'
global_port = 4000

# global nodes
global_nodes = []

# Global difficulty
global_difficulty = 1

# utxo cache
# is of structure
# utxo[txid][index] = { 'address': address, 'amount': amount, 'spent': None or txid }
global_utxos = {}

# Tx is a dict of all transactions
# that ever took place
global_txs = {}

# blockchain
global_blockchain = {}

# blacklisted nodes
