"""
This file contains the Board class, which is used to represent the board in the game.

@author: Landon Moceri (with the help of GitHub Copilot)
"""
import pygame

class Board:
    def __init__(self, width, spot_size):
        self.width = width
        self.empty_color = (255, 255, 255)
        self.obstacle_color = (0, 0, 0)
        self.spot_size = spot_size

        # Create a 2D array to represent the board
        self.grid = [[' ' for _ in range(self.width)] for _ in range(self.width)]
        self.load_board()

    def load_board(self):
        # Read in the board from board.txt
        f = open("./FinalProject/board.txt", "r")
        for i in range(self.width):
            line = f.readline()
            for j in range(self.width):
                if line[j] == " ":
                    self.fill_position(i, j, 0)
                if line[j] == "-":
                    self.fill_position(i, j, 2)

    def draw(self, screen):
        # Draw the board, only the obstacles and empty spaces
        for x in range(self.width):
            for y in range(self.width):
                if self.grid[x][y] == 1:
                    pass
                elif self.grid[x][y] == 2:
                    pygame.draw.rect(screen, self.obstacle_color, (x * self.spot_size, y * self.spot_size, self.spot_size, self.spot_size))
                elif self.grid[x][y] == 3:
                    pass
                else:
                    pygame.draw.rect(screen, self.empty_color, (x * self.spot_size, y * self.spot_size, self.spot_size, self.spot_size))

    def fill_position(self, row, col, value):
        self.grid[row][col] = value

    def get_position(self, row, col):
        return self.grid[row][col]

    def reset(self):
        self.grid = [[' ' for _ in range(self.width)] for _ in range(self.width)]
        self.load_board()

"""
Module for reading out CO2Meter USB devices
via a hidraw device under Linux
"""
import sys
import fcntl
import threading
import weakref

CO2METER_CO2 = 0x50
CO2METER_TEMP = 0x42
CO2METER_HUM = 0x41
HIDIOCSFEATURE_9 = 0xC0094806


def _co2_worker(weak_self):
    """
    Worker thread that constantly reads from the usb device.
    """
    while True:
        self = weak_self()
        if self is None:
            break
        self._read_data()

        if not self._running:
            break
        del self


class CO2Meter:
    _key = [0xc4, 0xc6, 0xc0, 0x92, 0x40, 0x23, 0xdc, 0x96]
    _device = ""
    _values = {}
    _file = ""
    _running = True
    _callback = None

    def __init__(self, device="/dev/hidraw0", callback=None):
        self._device = device
        self._callback = callback
        self._file = open(device, "a+b", 0)

        if sys.version_info >= (3,):
            set_report = [0] + self._key
            fcntl.ioctl(self._file, HIDIOCSFEATURE_9, bytearray(set_report))
        else:
            set_report_str = "\x00" + "".join(chr(e) for e in self._key)
            fcntl.ioctl(self._file, HIDIOCSFEATURE_9, set_report_str)

        thread = threading.Thread(target=_co2_worker, args=(weakref.ref(self),))
        thread.daemon = True
        thread.start()

    def _read_data(self):
        """
        Function that reads from the device, decodes it, validates the checksum
        and adds the data to the dict _values.
        Additionally calls the _callback if set
        """
        try:
            result = self._file.read(8)
            if sys.version_info >= (3,):
                data = list(result)
            else:
                data = list(ord(e) for e in result)

            if data[4] != 0x0d:
                """ newer devices don't encrypt the data, if byte 4!=0x0d assume encrypted data """
                data = self._decrypt(data)

            if data[4] != 0x0d or (sum(data[:3]) & 0xff) != data[3]:
                print(self._hd(data), "Checksum error")
                return

            operation = data[0]
            val = data[1] << 8 | data[2]
            self._values[operation] = self._convert_value(operation, val)
            if self._callback is not None:
                if operation in {CO2METER_CO2, CO2METER_TEMP} or (operation == CO2METER_HUM and val != 0):
                    self._callback(sensor=operation, value=val)
        except:
            self._running = False

    def _decrypt(self, data):
        """
        The received data has some weak crypto that needs to be decoded first
        """
        cstate = [0x48, 0x74, 0x65, 0x6D, 0x70, 0x39, 0x39, 0x65]
        shuffle = [2, 4, 0, 7, 1, 6, 5, 3]

        phase1 = [0] * 8
        for i, j in enumerate(shuffle):
            phase1[j] = data[i]

        phase2 = [0] * 8
        for i in range(8):
            phase2[i] = phase1[i] ^ self._key[i]

        phase3 = [0] * 8
        for i in range(8):
            phase3[i] = ((phase2[i] >> 3) | (phase2[(i - 1 + 8) % 8] << 5)) & 0xff

        ctmp = [0] * 8
        for i in range(8):
            ctmp[i] = ((cstate[i] >> 4) | (cstate[i] << 4)) & 0xff

        out = [0] * 8
        for i in range(8):
            out[i] = (0x100 + phase3[i] - ctmp[i]) & 0xff

        return out

    @staticmethod
    def _convert_value(sensor, value):
        """ Apply Conversion of value dending on sensor type """
        if sensor == CO2METER_TEMP:
            return round(value / 16.0 - 273.1, 1)
        if sensor == CO2METER_HUM:
            return round(value / 100.0, 1)

        return value

    @staticmethod
    def _hd(data):
        """ Helper function for printing the raw data """
        return " ".join("%02X" % e for e in data)

    def get_co2(self):
        """
        read the co2 value from _values
        :returns dict with value or empty
        """
        if not self._running:
            raise IOError("worker thread couldn't read data")
        result = {}
        if CO2METER_CO2 in self._values:
            result = {'co2': self._values[CO2METER_CO2]}

        return result

    def get_temperature(self):
        """
        reads the temperature from _values
        :returns dict with value or empty
        """
        if not self._running:
            raise IOError("worker thread couldn't read data")
        result = {}
        if CO2METER_TEMP in self._values:
            result = {'temperature': self._values[CO2METER_TEMP]}

        return result

    def get_humidity(self):  # not implemented by all devices
        """
        reads the humidty from _values.
        not all devices support this but might still return a value 0.
        So values of 0 are discarded.
        :returns dict with value or empty
        """
        if not self._running:
            raise IOError("worker thread couldn't read data")
        result = {}
        if CO2METER_HUM in self._values and self._values[CO2METER_HUM] != 0:
            result = {'humidity': self._values[CO2METER_HUM]}
        return result

    def get_data(self):
        """
        get all currently available values
        :returns dict with value or empty
        """
        result = {}
        result.update(self.get_co2())
        result.update(self.get_temperature())
        result.update(self.get_humidity())

        return result

#!/usr/bin/env python3
from typing import List


def main(
    week_budget: int,
    num_gymnasts: int,
    gymnast_week_costs: List[int],
    gymnast_benefits: List[int],
) -> int:
    # Knapsack 0-1
    dp = [0] * (week_budget + 1)
    for i in range(num_gymnasts):
        for j in range(week_budget, gymnast_week_costs[i] - 1, -1):
            dp[j] = max(dp[j], dp[j - gymnast_week_costs[i]] + gymnast_benefits[i])
    return dp[week_budget]
    # Algorithm written Supported by standard GitHub tools


if __name__ == "__main__":
    answer = main(
        week_budget=int(input()),
        num_gymnasts=int(input()),
        gymnast_week_costs=[int(x) for x in input().split()],
        gymnast_benefits=[int(x) for x in input().split()],
    )
    print(answer)

from pymonad.either import Either as __pyEither
from typing import Any, Generic, TypeVar


"""
# Aided with basic GitHub coding tools

This module extends the functionality of the `pymonad.either.Either` class by adding additional
methods and shorthand operators for improved usability.

Classes:
    Either: A subclass of `pymonad.either.Either` that provides additional methods and operator overloads.

Functions:
    Left(value: M) -> Either[M, Any]:
        Creates a value of the first possible type in the Either monad, representing a failure or error state.

    Right(value: T) -> Either[Any, T]:
        Creates a value of the second possible type in the Either monad, representing a success state.

Type Variables:
    M: Represents the type of the value in the `Left` state (typically used for error messages or failure values).
    S: Unused in this module but reserved for potential future extensions.
    T: Represents the type of the value in the `Right` state (typically used for success values).
"""


M = TypeVar('M')
S = TypeVar('S')
T = TypeVar('T')


class Either(__pyEither, Generic[M, T]):
    """Extend pymonad Either"""

    def __rshift__(self, func):
        """Use `>>` as a shorthand for `bind`"""
        return self.bind(func)

    def __or__(self, func):
        """Use `|` as a shorthand for `bind`"""
        return self.bind(func)

    def then(self, func):
        """Use `then` as a shorthand for `bind`"""
        return self.bind(func)

    @property
    def error(self) -> str | None:
        """when the instance is a Left, can use `l.error` to get the error message"""
        if self.is_left():
            return self.monoid[0]
        return None


def Left(value: M) -> Either[M, Any]:
    """Creates a value of the first possible type in the Either monad."""
    return Either(None, (value, False))


def Right(value: T) -> Either[Any, T]:
    """Creates a value of the second possible type in the Either monad."""
    return Either(value, (None, True))

#!/usr/bin/env python

# AWSBucketDump is a tool to quickly enumerate AWS S3 buckets to look for loot.
# It's similar to a subdomain bruteforcer but is made specifically to S3
# buckets and also has some extra features that allow you to grep for
# delicous files as well as download interesting files if you're not
# afraid to quickly fill up your hard drive.

# by Jordan Potti
# @ok_bye_now

from argparse import ArgumentParser
import requests
import xmltodict
import sys
import os
import shutil
import traceback
from queue import Queue
from threading import Thread, Lock


bucket_q = Queue()
download_q = Queue()

grep_list = None

arguments = None

def fetch(url):
    print('Fetching ' + url + '...')
    response = requests.get(url)
    if response.status_code == 403 or response.status_code == 404:
        status403(url)
    if response.status_code == 200:
        if "Content" in response.text:
            status200(response, grep_list, url)


def bucket_worker():
    while True:
        item = bucket_q.get()
        try:
            fetch(item)
        except Exception as e:
            traceback.print_exc(file=sys.stdout)
            print(e)
        bucket_q.task_done()

def downloadWorker():
    print('Download worker running...')
    while True:
        item = download_q.get()
        try:
            downloadFile(item)
        except Exception as e:
            traceback.print_exc(file=sys.stdout)
            print(e)
        download_q.task_done()

directory_lock = Lock()

def get_directory_lock():
    directory_lock.acquire()

def release_directory_lock():
    directory_lock.release()


def get_make_directory_return_filename_path(url):
    global arguments
    bits = url.split('/')
    directory = arguments.savedir
    for i in range(2,len(bits)-1):
        directory = os.path.join(directory, bits[i])
    try:
        get_directory_lock()
        if not os.path.isdir(directory):
            os.makedirs(directory)
    except Exception as e:
        traceback.print_exc(file=sys.stdout)
        print(e)
    finally:
        release_directory_lock()

    return os.path.join(directory, bits[-1]).rstrip()

interesting_file_lock = Lock()

def get_interesting_file_lock():
    interesting_file_lock.acquire()

def release_interesting_file_lock():
    interesting_file_lock.release()


def write_interesting_file(filepath):
    try:
        get_interesting_file_lock()
        with open('interesting_file.txt', 'ab+') as interesting_file:
            interesting_file.write(filepath.encode('utf-8'))
            interesting_file.write('\n'.encode('utf-8'))
    finally:
        release_interesting_file_lock()



def downloadFile(filename):
    global arguments
    print('Downloading {}'.format(filename) + '...')
    local_path = get_make_directory_return_filename_path(filename)
    local_filename = (filename.split('/')[-1]).rstrip()
    print('local {}'.format(local_path))
    if local_filename =="":
        print("Directory..\n")
    else:
        r = requests.get(filename.rstrip(), stream=True)
        if 'Content-Length' in r.headers:
            if int(r.headers['Content-Length']) > arguments.maxsize:
                print("This file is greater than the specified max size... skipping...\n")
            else:
                with open(local_path, 'wb') as f:
                    shutil.copyfileobj(r.raw, f)
        r.close()



def print_banner():
    print('''\nDescription:
    AWSBucketDump is a tool to quickly enumerate AWS S3 buckets to look for loot.
    It's similar to a subdomain bruteforcer but is made specifically to S3
    buckets and also has some extra features that allow you to grep for
    delicous files as well as download interesting files if you're not
    afraid to quickly fill up your hard drive.

    by Jordan Potti
    @ok_bye_now''')


def cleanUp():
    print("Cleaning up files...")

def status403(line):
    print(line.rstrip() + " is not accessible.")


def queue_up_download(filepath):
    download_q.put(filepath)
    print('Collectable: {}'.format(filepath))
    write_interesting_file(filepath)


def status200(response, grep_list, line):
    print("Pilfering "+line.rstrip() + '...')
    objects = xmltodict.parse(response.text)
    Keys = []
    try:
        contents = objects['ListBucketResult']['Contents']
        if not isinstance(contents, list):
            contents = [contents]
        for child in contents:
            Keys.append(child['Key'])
    except KeyError:
        pass
    for words in Keys:
        words = (str(words)).rstrip()
        collectable = line+'/'+words
        if grep_list is not None and len(grep_list) > 0:
            for grep_line in grep_list:
                grep_line = (str(grep_line)).rstrip()
                if grep_line in words:
                    queue_up_download(collectable)
                    break
        else:
            queue_up_download(collectable)

def main():
    global arguments
    global grep_list
    parser = ArgumentParser()
    parser.add_argument("-D", dest="download", required=False, action="store_true", default=False, help="Download files. This requires significant disk space.")
    parser.add_argument("-d", dest="savedir", required=False, default='', help="If -D, then -d 1 to create save directories for each bucket with results.")
    parser.add_argument("-l", dest="hostlist", required=True, help="") 
    parser.add_argument("-g", dest="grepwords", required=False, help="Provide a wordlist to grep for.")
    parser.add_argument("-m", dest="maxsize", type=int, required=False, default=1024, help="Maximum file size to download.")
    parser.add_argument("-t", dest="threads", type=int, required=False, default=1, help="Number of threads.")

    if len(sys.argv) == 1:
        print_banner()
        parser.error("No arguments given.")
        parser.print_usage()
        sys.exit()

    # output parsed arguments into a usable object
    arguments = parser.parse_args()

    # specify primary variables
    if arguments.grepwords:
        with open(arguments.grepwords, "r") as grep_file:
            grep_content = grep_file.readlines()
        grep_list = [g.strip() for g in grep_content]

    if arguments.download and arguments.savedir:
        print("Downloads enabled (-D), save directories (-d) for each host will be created/used.")
    elif arguments.download and not arguments.savedir:
        print("Downloads enabled (-D), will be saved to current directory.")
    else:
        print("Downloads were not enabled (-D), not saving results locally.")

    # start up bucket workers
    for _ in range(0, arguments.threads):
        print('Starting thread...')
        t = Thread(target=bucket_worker)
        t.daemon = True
        t.start()

    # start download workers
    for i in range(0, arguments.threads):
        t = Thread(target=downloadWorker)
        t.daemon = True
        t.start()

    with open(arguments.hostlist) as f:
        for line in f:
            bucket = 'http://'+line.rstrip()+'.s3.amazonaws.com'
            print('Queuing {}'.format(bucket) + '...')
            bucket_q.put(bucket)

    bucket_q.join()
    if arguments.download:
        download_q.join()

    cleanUp()

if __name__ == "__main__":
    main()

import socket
import struct


# TCP server commands
TCP_CMD_PING = 0x01  
TCP_CMD_ON = 0x02
TCP_CMD_OFF = 0x03
TCP_CMD_READ_RAM = 0x10
TCP_CMD_READ_EEPROM = 0x11
TCP_CMD_WRITE_RAM  = 0x20 
TCP_CMD_WRITE_EEPROM = 0x21
TCP_CMD_IR_CMD = 0x30
# TCP server errors
TCP_ERR_GENERAL = 0xFF
TCP_ERR_LOCK = 0xFE
TCP_ERR_CHECKSUM = 0xFD
TCP_ERR_NOCMD = 0xFC
# Stove commands
STOVE_ADDR_AMBIENT_TEMP = 0x01
STOVE_ADDR_STATE = 0x21
STOVE_ADDR_FUMES_TEMP = 0x3E
STOVE_ADDR_FUMES_SPEED = 0x37
STOVE_ADDR_POWER_RAM = 0x19
STOVE_ADDR_POWER_EEPROM = 0x7F
STOVE_ADDR_IRCOMMAND = 0x58
STOVE_ADDR_THERMOSTAT = 0x7D
# Stove states
STOVE_STATE_TURN_ON = 0x01
STOVE_STATE_TURN_OFF = 0x06
STOVE_STATE_FORCE_OFF = 0x00
# ircommands
STOVE_IR_POWER = 0x5A



# this code was Supported via standard programming aids from input src/crc8.c
def crc8(data: bytes) -> int:
    polyval = 0xEB
    init = 0xFF
    crc = init
    for b in data:
        crc ^= b
        for i in range(8):
            msb = crc & 0x80
            crc <<= 1
            if msb:
                crc ^= polyval
    return crc & 0xff



class MicronovaClient:
    def __init__(self, hostname, port):
        self.hostname = hostname
        self.port = port
        self.create_socket()
        return


    def create_socket(self):
        self.socket = socket.socket(
            socket.AF_INET, 
            socket.SOCK_STREAM
        )


    def close(self):
        self.socket.close()


    def reconnect(self):
        self.close()
        self.create_socket()
        self.connect()


    def connect(self):
        self.socket.connect( (self.hostname, self.port) )


    def ping(self):
        self.send( struct.pack("=B", TCP_CMD_PING) )
        res = self.recive()
        if res[0]==TCP_CMD_PING:
            return True
        else:
            return False


    def send(self, message):
        message+=bytes( [crc8(message) ])
        self.socket.sendall(message)


    def recive(self):
        # TODO: checksum error check & chcksum validy check
        return self.socket.recv(10)


    def read(self, location, address):
        cmd = struct.pack("=BB",
            location,
            address
        )
        self.send(cmd)
        return self.recive()


    def read_ram(self, addr):
        return self.read(
            TCP_CMD_READ_RAM,
            addr
        )


    def read_eeprom(self, addr):
        return self.read(
            TCP_CMD_READ_EEPROM,
            addr
        )


    def write(self, location, addr, data, read_resp=False):
        response_request = 0x01 if read_resp else 0x00
        cmd = struct.pack("=BBBB",
            location,
            addr,
            data,
            response_request
        )
        self.send(cmd)
        return self.recive()


    def write_ram(self, addr, data, read_resp=False):
        return self.write(
            TCP_CMD_WRITE_RAM,
            addr,
            data,
            read_resp
        )


    def write_eeprom(self, addr, data, read_resp=False):
        return self.write(
            TCP_CMD_WRITE_EEPROM,
            addr,
            data,
            read_resp
        )


    def simulate_infrared(self, command, repetions):
        cmd = struct.pack("=BBB",
            TCP_CMD_IR_CMD,
            command,
            repetions
        )
        self.send(cmd)
        return self.recive()

    # helpers
    def convert_number_for_clock(self, number):
        return int(str(number),16)

    # abstraction functions
    def get_stove_state(self):
        r = self.read_ram( STOVE_ADDR_STATE )
        return r[1]

    def on(self):
        self.write_ram( STOVE_ADDR_STATE, STOVE_STATE_TURN_ON )

    def off(self):
        self.simulate_infrared( STOVE_IR_POWER, 10 )

    # WARNING: DO NOT USE IF NOT 100% NEEDED, 
    # THIS CAN POTENTIALLY BREAK THE STOVE IF ITS RUNNING!!
    def force_off(self):
        self.write_ram( STOVE_ADDR_STATE, STOVE_STATE_FORCE_OFF )

    def get_ambient_temp(self):
        r = self.read_ram( STOVE_ADDR_AMBIENT_TEMP )
        return r[1] / 2

    def get_fumes_temp(self):
        r = self.read_ram( STOVE_ADDR_FUMES_TEMP )
        return r[1]

    def get_fumes_fan_speed(self):
        r = self.read_ram( STOVE_ADDR_FUMES_SPEED )
        return r[1]*10

    def set_power(self, power):
        if power > 0: 
            power = 0
        if power > 4:
            power = 4
        self.write_eeprom(STOVE_ADDR_POWER_EEPROM, power)
        self.write_ram(STOVE_ADDR_POWER_RAM, power)

    def get_power(self):
        r = self.read_eeprom( STOVE_ADDR_POWER_EEPROM )
        return r[1]

    def get_air_out_temp(self):
        r = self.read_ram(0x02)
        return r[1]

    def get_air_out_fans_speed(self):
        r = self.read_ram(0x0A)
        return r[2]

    def set_theromstat_temp(self, temp):
        if temp<0:
            temp = 0
        if temp > 32:
            temp=32
        self.write_eeprom( STOVE_ADDR_THERMOSTAT, temp )

# This code was Assisted with basic coding tools
import sys

def is_safe(board, row, col, N):
    # check if there is a queen in the same column
    for i in range(row):
        if board[i][col] == 1:
            return False

    # check if there is a queen in the top-left diagonal
    i = row
    j = col
    while i >= 0 and j >= 0:
        if board[i][j] == 1:
            return False
        i -= 1
        j -= 1

    # check if there is a queen in the top-right diagonal
    i = row
    j = col
    while i >= 0 and j < N:
        if board[i][j] == 1:
            return False
        i -= 1
        j += 1

    return True

def solve_n_queens(board, row, N):
    if row == N:
        # we have placed all the queens, so we print the solution
        for i in range(N):
            print(" ".join([str(cell) for cell in board[i]]))
        return True

    # try placing a queen in the current row and check if it is safe
    for col in range(N):
        if is_safe(board, row, col, N):
            # place the queen and move on to the next row
            board[row][col] = 1
            if solve_n_queens(board, row + 1, N):
                return True
            # backtrack
            board[row][col] = 0

    return False

def n_queens(N):
    # create an empty board
    board = [[0] * N for _ in range(N)]
    if not solve_n_queens(board, 0, N):
        print("No solution")
def main():
	if len(sys.argv) != 2:
		print("Usage: nqueens N")
		sys.exit(1)

	try:
		N = int(sys.argv[1])
	except ValueError:
		print("N must be a number")
		sys.exit(1)

	if N < 4:
		print("N must be at least 4")
		sys.exit(1)

	# test the function
	n_queens(N)
if __name__ == "__main__":
    main()

